p_id: str\\n    revision: int = Field(ge=1)\\n    collaboration_id: str\\n    contract_ref: CreatorExactRef\\n    delivery_observation_refs: list[CreatorExactRef]\\n    maturity_policy_ref: CreatorExactRef\\n    maturity_window_ends_at: datetime\\n    status: str = Field(pattern=r\\\"^(preliminary|mature|at_risk)$\\\")\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\n    created_at: datetime\\nclass CreatorLifecycleView(AipContractModel):\\n    schema_version: str = CREATOR_LIFECYCLE_SCHEMA_VERSION\\n    tenant: TenantContext\\n    evaluated_at: datetime\\n    latest_start: CreatorBatchStartDecisionRevision | None\\n    ledger: CreatorBatchStartLedger\\n    contracts: list[CreatorContractRevision]\\n    deliveries: list[CreatorDeliveryObservation]\\n    relationships: list[CreatorRelationshipRevision]\\n    blockers: list[str]\\n    allowed_commands: list[str] = Field(default_factory=lambda: [\\\"START_CREATOR_BATCH_GOVERNANCE\\\"])\\n    external_effects_allowed: bool = False\\ndef _ledger(lanes: list[CreatorActionLaneBinding], eligible: int) -> CreatorBatchStartLedger:\\n    counts = {outcome.value: 0 for outcome in CreatorLaneOutcome}\\n    for lane in lanes:\\n        counts[(lane.resolved_outcome or lane.outcome).value] += 1\\n    return CreatorBatchStartLedger(\\n        eligibleItems=eligible,\\n        lanes=len(lanes),\\n        **counts,\\n        completed=counts[CreatorLaneOutcome.APPLIED.value] + counts[CreatorLaneOutcome.FAILED.value],\\n    )\\ndef view(self, scope: TenantScope, *, now: datetime | None = None) -> CreatorLifecycleView:\\n        at = now or datetime.now(UTC)\\n        try:\\n            start = self.store.latest_start_for_tenant_or_none(scope)\\n            observations = self.store.list_lane_observations(scope, start.decision_id) if start else []\\n            contracts = self.store.list_contracts(scope)\\n            deliveries = self.store.list_deliveries(scope)\\n            relationships = self.store.list_relationships(scope)\\n        except CreatorLifecycleBlocked as exc:\\n            if str(exc) != \\\"CREATOR_LIFECYCLE_AUTHORITY_UNAVAILABLE\\\":\\n                raise\\n            return CreatorLifecycleView(\\n                tenant=self._tenant(scope), evaluatedAt=at, latestStart=None,\\n                ledger=_ledger([], 0), contracts=[], deliveries=[], relationships=[],\\n                blockers=[\\\"CREATOR_LIFECYCLE_AUTHORITY_UNAVAILABLE\\\", \\\"CREATOR_BATCH_START_NOT_AVAILABLE\\\"],\\n            )\\n        lanes = list(start.lanes) if start else []\\n        latest_by_lane: dict[str, CreatorLaneObservation] = {}\\n        for observation in observations:\\n            latest_by_lane[observation.lane_id] = observation\\n        if start:\\n            lanes = [lane.model_copy(update={\\\"outcome\\\": latest_by_lane[lane.lane_id].outcome, \\\"resolved_outcome\\\": latest_by_lane[lane.lane_id].resolved_outcome, \\\"action_receipt_ref\\\": latest_by_lane[lane.lane_id].action_receipt_ref}) if lane.lane_id in latest_by_lane else lane for lane in lanes]\\n            start = start.model_copy(update={\\\"lanes\\\": lanes, \\\"ledger\\\": _ledger(lanes, start.ledger.eligible_items)})\\n        blockers = list(start.operational_blockers) if start else [\\\"CREATOR_BATCH_START_NOT_AVAILABLE\\\"]\\n        return CreatorLifecycleView(\\n            tenant=self._tenant(scope), evaluatedAt=at, latestStart=start,\\n            ledger=_ledger(lanes, start.ledger.eligible_items if start else 0),\\n            contracts=contracts, deliveries=deliveries, relationships=relationships, blockers=blockers,\\n        )\\nEXACT CURRENT NAMED SOURCE services/aos-api/aos_api/ecommerce_workshop_creator_growth_authorities.py SHA db88444393f0fbec05ec5d7cebd26885442b1b1e50280cbdfae4efb0f43cc317\\nclass CreatorExactRef(AipContractModel):\\n    resource_type: str = Field(min_length=1, max_length=100)\\n    resource_id: str = Field(min_length=1, max_length=200)\\n    revision: int = Field(ge=1)\\n    content_hash: str = Field(pattern=r\\\"^[0-9a-f]{64}$\\\")\\nEXACT CURRENT NAMED SOURCE services/aos-api/aos_api/db.py SHA a028af42c86a71426c7e3c165c50f87bddcf8cc17da8a6bb8972c4da70d93010\\ndef _connect(\\n    scope: TenantScope | None = None,\\n    *,\\n    inherit_scope: bool = True,\\n    read_only: bool = False,\\n    isolation_level: IsolationLevel | None = None,\\n    platform_role: bool = False,\\n) -> Iterator[psycopg.Connection]:\\n    dsn = get_dsn()\\n    log.debug(\\\"db_connect host_port_from_env=%s\\\", \\\"AOS_DATABASE_URL\\\" in os.environ)\\n    with psycopg.connect(dsn, row_factory=dict_row) as conn:\\n        # psycopg applies these characteristics when the transaction starts.\\n        # They must be configured before client encoding or tenant RLS executes\\n        # the first SQL statement; issuing SET TRANSACTION afterwards fails.\\n        if isolation_level is not None:\\n            conn.isolation_level = isolation_level\\n        if read_only:\\n            conn.read_only = True\\n        # 强制 UTF-8，避免客户端/驱动默认编码把中文写成 ???\\n        conn.execute(\\\"SET client_encoding TO 'UTF8'\\\")\\n        effective_scope = (\\n            scope\\n            if scope is not None\\n            else (current_tenant_scope() if inherit_scope else None)\\n        )\\n        if effective_scope is not None:\\n            apply_transaction_scope(conn, effective_scope)\\n        elif platform_role:\\n            # Scope-less but still authenticated as the runtime role: needed on\\n            # a NOINHERIT login where omitting SET ROLE means \\\"no privileges at\\n            # all\\\". Never grants tenant visibility — the GUCs stay unset.\\n            apply_platform_role(conn)\\n        else:\\n            # Scope-less AND no platform role: on a NOINHERIT login this\\n            # connection can read nothing at all, and the failure surfaces as\\n            # \\\"permission denied\\\" deep inside whichever statement runs first.\\n            # Attribute the caller so the residual offenders can be census'd\\n            # instead of guessed (see W6 connection-plane debt work).\\n            try:\\n                frame = sys._getframe(2)\\n                caller = f\\\"{frame.f_code.co_filename.rsplit('/', 1)[-1]}:{frame.f_lineno}\\\"\\n            except ValueError:  # shallow stack — never let diagnostics break a connect\\n                caller = \\\"unknown\\\"\\n            log.debug(\\\"db_connect_without_scope caller=%s\\\", caller)\\n        yield conn\\ndef connect_read_only(\\n    scope: TenantScope | None = None,\\n    *,\\n    inherit_scope: bool = True,\\n    platform_role: bool = False,\\n) -> Iterator[psycopg.Connection]:\\n    \\\"\\\"\\\"Open a repeatable-read, read-only transaction before applying RLS scope.\\n\\n    Pass ``scope=None, inherit_scope=False, platform_role=True`` to read\\n    platform-level assets (no tenant RLS) with the runtime identity: a\\n    scope-less connection performs no SET ROLE, which on a NOINHERIT login\\n    leaves the session with no privileges at all.\\n    \\\"\\\"\\\"\\n    return _connect(\\n        scope,\\n        inherit_scope=inherit_scope,\\n        read_only=True,\\n        isolation_level=IsolationLevel.REPEATABLE_READ,\\n        platform_role=platform_role,\\n    )\\nEXACT CURRENT NAMED SOURCE services/aos-api/aos_api/routers/ecommerce_workshop.py SHA b5e9087ff769415fb7aca5cce820043b83b4b1edd2edabec3957ff0a9bfdead9\\ndef _require_creator_growth_installation(\\n    *, principal: Principal, catalog: EcommerceWorkshopCatalog\\n) -> None:\\n    _invoke(\\n        lambda: catalog.get_readiness(\\n            module_id=\\\"ecommerce.creator-growth\\\",\\n            org_id=principal.org_id,\\n            project_id=principal.project_id,\\n            roles=principal.roles,\\n            markings=principal.markings,\\n        )\\n    )\\ndef get_creator_lifecycle_view(\\n    request: Request,\\n    principal: PrincipalDependency,\\n    catalog: CatalogDependency,\\n    service: CreatorLifecycleDependency,\\n) -> CreatorLifecycleView:\\n    _reject_query_parameters(request)\\n    _require_creator_growth_installation(principal=principal, catalog=catalog)\\n    return service.view(TenantScope(principal.org_id, principal.project_id))\"}}"}],"timestamp":1791977169802}}
